def squash(s: str) -> str:
    if not s:
        return ""

    def esc(c: str) -> str:
        if c.isdigit() or c == '\\':
            return '\\' + c
        return c

    # Build runs of consecutive identical characters
    runs = []
    i = 0
    while i < len(s):
        c = s[i]
        j = i
        while j < len(s) and s[j] == c:
            j += 1
        runs.append((c, j - i))
        i = j

    result = []
    for c, length in runs:
        if length >= 3:
            result.append(str(length))
            result.append(esc(c))
        else:
            result.append(esc(c) * length)

    return ''.join(result)
